    body: {
      type: "object",
      required: ["name", "email"],
      properties: {
        name: { type: "string", minLength: 1 },
        email: { type: "string", format: "email" }
      }
    },
    response: {
      201: {
        type: "object",
        properties: {
          id: { type: "string" },
          name: { type: "string" },
          email: { type: "string" }
        }
      }
    }
  }
}, async (request, reply) => {
  const user = await createUser(request.body);
  return reply.code(201).send(user);
});

// Hooks
